import type { AttendanceEntry } from '../../core/index.js';

/**
 * Pure helpers behind the browser <-> server sync (no network, no storage), kept here so they are unit-tested
 * with the rest of the engine and shared by the frontend through the vendor sync.
 */

export interface PushChange {
  entity: string;
  id: string;
  /** the record, or null to delete it */
  data: unknown | null;
}

export interface BatchLimits {
  maxItems: number;
  maxBytes: number;
}

export const DEFAULT_BATCH_LIMITS: BatchLimits = { maxItems: 200, maxBytes: 900_000 };

/**
 * Splits changes into request-sized batches, preserving order: at most `maxItems` records and roughly `maxBytes`
 * of JSON per batch. A record bigger than `maxBytes` (a large seating allocation) travels alone, so a heavy record
 * never drags a whole batch over the limit.
 */
export function batchChanges(changes: PushChange[], limits: BatchLimits = DEFAULT_BATCH_LIMITS): PushChange[][] {
  const batches: PushChange[][] = [];
  let current: PushChange[] = [];
  let bytes = 0;
  for (const change of changes) {
    const size = change.data === null ? 60 : JSON.stringify(change.data).length + 60;
    if (current.length > 0 && (current.length >= limits.maxItems || bytes + size > limits.maxBytes)) {
      batches.push(current);
      current = [];
      bytes = 0;
    }
    current.push(change);
    bytes += size;
  }
  if (current.length > 0) batches.push(current);
  return batches;
}

// ------------------------------------------------------------------------------------------------ attendance
// Attendance is stored locally as one record per exam (fast to read), but synced one row per (exam, roll), so two
// people marking different rooms never overwrite each other.

export const attendanceMarkId = (examId: string, roll: string): string => `${examId}:${roll}`;

/** examId is generated (no colon); the roll is everything after the first colon. */
export function parseAttendanceMarkId(id: string): { examId: string; roll: string } | null {
  const i = id.indexOf(':');
  return i > 0 && i < id.length - 1 ? { examId: id.slice(0, i), roll: id.slice(i + 1) } : null;
}

/** Cheap fingerprint of an entry, used to detect what changed since the last sync. */
export const markSignature = (e: AttendanceEntry): string => `${e.mark}|${e.markedAt}|${e.reason ?? ''}|${e.note ?? ''}|${e.name ?? ''}|${e.branch ?? ''}`;

export type SyncedMarks = Record<string, string>; // roll -> signature as of the last sync

/** Which marks to push: new / changed entries, and entries that were removed since the last sync (deletes). */
export function diffAttendance(examId: string, entries: Record<string, AttendanceEntry>, synced: SyncedMarks): { changes: PushChange[]; nextSynced: SyncedMarks } {
  const changes: PushChange[] = [];
  const nextSynced: SyncedMarks = {};
  for (const [roll, entry] of Object.entries(entries)) {
    const sig = markSignature(entry);
    nextSynced[roll] = sig;
    if (synced[roll] !== sig) changes.push({ entity: 'attendanceMark', id: attendanceMarkId(examId, roll), data: entry });
  }
  for (const roll of Object.keys(synced)) {
    if (!(roll in entries)) changes.push({ entity: 'attendanceMark', id: attendanceMarkId(examId, roll), data: null });
  }
  return { changes, nextSynced };
}

export interface PulledMark {
  roll: string;
  /** null = the mark was removed (back to present) */
  entry: AttendanceEntry | null;
}

/**
 * Applies marks pulled from the server on top of the local entries. Per roll number the newer `markedAt` wins, so an
 * older pulled mark never undoes a fresher local one; a removal applies unless the local mark is newer than the
 * removal's knowledge (a local mark that is still unsynced is kept - it will be pushed next).
 */
export function mergePulledMarks(
  entries: Record<string, AttendanceEntry>,
  synced: SyncedMarks,
  pulled: PulledMark[]
): { entries: Record<string, AttendanceEntry>; synced: SyncedMarks; changed: number } {
  const out = { ...entries };
  const nextSynced = { ...synced };
  let changed = 0;
  for (const { roll, entry } of pulled) {
    const local = out[roll];
    const localUnsynced = local ? synced[roll] !== markSignature(local) : false;
    if (entry === null) {
      if (local && !localUnsynced) {
        delete out[roll];
        changed++;
      }
      if (!localUnsynced) delete nextSynced[roll];
      continue;
    }
    if (local && localUnsynced && local.markedAt >= entry.markedAt) continue; // local edit is newer and still pending
    if (!local || markSignature(local) !== markSignature(entry)) changed++;
    out[roll] = entry;
    nextSynced[roll] = markSignature(entry);
  }
  return { entries: out, synced: nextSynced, changed };
}

// ------------------------------------------------------------------------------------------------ retry
/** 1 min, 2 min, 5 min, then 10 min: waiting time after the n-th consecutive failed sync (n >= 1). */
export function retryDelayMs(consecutiveFailures: number): number {
  const steps = [60_000, 120_000, 300_000, 600_000];
  return steps[Math.min(Math.max(consecutiveFailures, 1), steps.length) - 1]!;
}

/** Local settings keys that are shared through the server (everything else, e.g. this device's sync options, stays local). */
export const SYNCED_SETTING_KEYS = ['dutyWindows', 'mixGroups', 'institutionProfile'] as const;

/** Which roles may change which record types; mirrors the server so the app can refuse early with a clear message. */
export type OrgRole = 'org_admin' | 'exam_cell' | 'attendance_marker' | 'viewer';
export function roleCanWrite(role: OrgRole, entity: string): boolean {
  if (role === 'org_admin' || role === 'exam_cell') return true;
  if (role === 'attendance_marker') return entity === 'attendance' || entity === 'attendanceMark';
  return false;
}
